1	package com.loja.checkout.servico;
2	
3	import com.loja.checkout.dominio.*;
4	import com.loja.checkout.dominio.cupom.Cupom;
5	import com.loja.checkout.dominio.entrega.ModalidadeEntrega;
6	import com.loja.checkout.dominio.pagamento.FormaPagamento;
7	import com.loja.checkout.dominio.clube.NivelClube;
8	import com.loja.checkout.dto.*;
9	import com.loja.checkout.util.Arredondamento;
10	import org.springframework.stereotype.Service;
11	
12	import java.math.BigDecimal;
13	
14	@Service
15	public class CalculadoraResumo {
16	
17	    private final CupomFactory cupomFactory;
18	    private final ModalidadeEntregaFactory modalidadeFactory;
19	    private final FormaPagamentoFactory pagamentoFactory;
20	    private final NivelClubeFactory clubeFactory;
21	
22	    public CalculadoraResumo(
23	        CupomFactory cupomFactory,
24	        ModalidadeEntregaFactory modalidadeFactory,
25	        FormaPagamentoFactory pagamentoFactory,
26	        NivelClubeFactory clubeFactory
27	    ) {
28	        this.cupomFactory = cupomFactory;
29	        this.modalidadeFactory = modalidadeFactory;
30	        this.pagamentoFactory = pagamentoFactory;
31	        this.clubeFactory = clubeFactory;
32	    }
33	
34	    public ResumoResponse calcular(PedidoRequest pedido) {
35	        validarPedidoBasico(pedido);
36	
37	        NivelClube nivelClube = obterNivelClube(pedido.nivelClube());
38	        Regiao regiao = obterRegiao(pedido.regiao());
39	        ModalidadeEntrega modalidade = obterModalidadeEntrega(pedido.modalidadeEntrega());
40	
41	        ContextoPedido contexto = criarContexto(pedido);
42	
43	        validarDisponibilidadeModalidade(modalidade, contexto);
44	
45	        BigDecimal freteBruto = calcularFreteBruto(modalidade, contexto);
46	        int prazoEntrega = modalidade.calcular(contexto).prazoEntregaDias();
47	
48	        Cupom cupom = obterCupom(pedido.cupom());
49	        validarCupom(cupom, contexto, freteBruto);
50	
51	        BigDecimal descontoCupom = calcularDescontoCupom(cupom, contexto, freteBruto);
52	
53	        ResultadoClube resultadoClube = nivelClube.calcular(contexto.getSubtotalProdutos());
54	        BigDecimal frete = aplicarFreteGratisSeNecessario(freteBruto, resultadoClube);
55	
56	        BigDecimal seguro = calcularSeguro(contexto.getSubtotalProdutos(), regiao);
57	        BigDecimal totalPedido = calcularTotalPedido(
58	            contexto.getSubtotalProdutos(),
59	            descontoCupom,
60	            frete,
61	            seguro
62	        );
63	
64	        FormaPagamento formaPagamento = obterFormaPagamento(pedido.formaPagamento());
65	        int parcelas = obterParcelas(pedido);
66	
67	        validarParcelamento(formaPagamento, parcelas);
68	        validarDisponibilidadeFormaPagamento(formaPagamento, totalPedido);
69	
70	        ResultadoPagamento resultadoPagamento = formaPagamento.calcular(totalPedido, parcelas);
71	
72	        return new ResumoResponse(
73	            contexto.getSubtotalProdutos(),
74	            descontoCupom,
75	            frete,
76	            prazoEntrega,
77	            seguro,
78	            resultadoPagamento.ajustePagamento(),
79	            resultadoPagamento.totalFinal(),
80	            resultadoPagamento.parcelas(),
81	            resultadoPagamento.valorParcela(),
82	            resultadoClube.creditoProximaCompra(),
83	            resultadoClube.brinde()
84	        );
85	    }
86	
87	    private void validarPedidoBasico(PedidoRequest pedido) {
88	        if (pedido.itens() == null || pedido.itens().isEmpty()) {
89	            throw new ErroNegocioException("PEDIDO_INVALIDO");
90	        }
91	
92	        for (ItemCarrinho item : pedido.itens()) {
93	            if (item.precoUnitario() == null ||
94	                item.precoUnitario().compareTo(BigDecimal.ZERO) <= 0 ||
95	                item.quantidade() == null ||
96	                item.quantidade() <= 0 ||
97	                item.pesoKg() == null ||
98	                item.pesoKg().compareTo(BigDecimal.ZERO) <= 0) {
99	                throw new ErroNegocioException("PEDIDO_INVALIDO");
100	            }
101	        }
102	    }
103	
104	    private NivelClube obterNivelClube(String codigo) {
105	        if (codigo == null) {
106	            throw new ErroNegocioException("NIVEL_CLUBE_INVALIDO");
107	        }
108	        NivelClube nivel = clubeFactory.obter(codigo);
109	        if (nivel == null) {
110	            throw new ErroNegocioException("NIVEL_CLUBE_INVALIDO");
111	        }
112	        return nivel;
113	    }
114	
115	    private Regiao obterRegiao(String codigo) {
116	        if (codigo == null) {
117	            throw new ErroNegocioException("REGIAO_INVALIDA");
118	        }
119	        try {
120	            return Regiao.valueOf(codigo);
121	        } catch (IllegalArgumentException e) {
122	            throw new ErroNegocioException("REGIAO_INVALIDA");
123	        }
124	    }
125	
126	    private ModalidadeEntrega obterModalidadeEntrega(String codigo) {
127	        if (codigo == null) {
128	            throw new ErroNegocioException("MODALIDADE_INVALIDA");
129	        }
130	        ModalidadeEntrega modalidade = modalidadeFactory.obter(codigo);
131	        if (modalidade == null) {
132	            throw new ErroNegocioException("MODALIDADE_INVALIDA");
133	        }
134	        return modalidade;
135	    }
136	
137	    private ContextoPedido criarContexto(PedidoRequest pedido) {
138	        ContextoPedido contexto = new ContextoPedido(pedido.itens());
139	
140	        BigDecimal subtotal = BigDecimal.ZERO;
141	        BigDecimal pesoTotal = BigDecimal.ZERO;
142	
143	        for (ItemCarrinho item : pedido.itens()) {
144	            BigDecimal valorItem = item.precoUnitario()
145	                .multiply(BigDecimal.valueOf(item.quantidade()));
146	            subtotal = subtotal.add(valorItem);
147	
148	            BigDecimal pesoItem = item.pesoKg()
149	                .multiply(BigDecimal.valueOf(item.quantidade()));
150	            pesoTotal = pesoTotal.add(pesoItem);
151	        }
152	
153	        contexto.setSubtotalProdutos(Arredondamento.arredondar(subtotal));
154	        contexto.setPesoTotal(pesoTotal);
155	
156	        return contexto;
157	    }
158	
159	    private void validarDisponibilidadeModalidade(ModalidadeEntrega modalidade, ContextoPedido contexto) {
160	        if (!modalidade.estaDisponivel(contexto)) {
161	            throw new ErroNegocioException("MODALIDADE_INDISPONIVEL");
162	        }
163	    }
164	
165	    private BigDecimal calcularFreteBruto(ModalidadeEntrega modalidade, ContextoPedido contexto) {
166	        return modalidade.calcular(contexto).frete();
167	    }
168	
169	    private Cupom obterCupom(String codigo) {
170	        if (codigo == null || codigo.isEmpty()) {
171	            return null;
172	        }
173	        Cupom cupom = cupomFactory.obter(codigo);
174	        if (cupom == null) {
175	            throw new ErroNegocioException("CUPOM_INVALIDO");
176	        }
177	        return cupom;
178	    }
179	
180	    private void validarCupom(Cupom cupom, ContextoPedido contexto, BigDecimal frete) {
181	        if (cupom != null && !cupom.podeAplicar(contexto, frete)) {
182	            throw new ErroNegocioException("CUPOM_NAO_APLICAVEL");
183	        }
184	    }
185	
186	    private BigDecimal calcularDescontoCupom(Cupom cupom, ContextoPedido contexto, BigDecimal frete) {
187	        if (cupom == null) {
188	            return new BigDecimal("0.00");
189	        }
190	        return cupom.calcularDesconto(contexto, frete);
191	    }
192	
193	    private BigDecimal aplicarFreteGratisSeNecessario(BigDecimal frete, ResultadoClube resultadoClube) {
194	        if (resultadoClube.freteGratis()) {
195	            return new BigDecimal("0.00");
196	        }
197	        return frete;
198	    }
199	
200	    private BigDecimal calcularSeguro(BigDecimal subtotalProdutos, Regiao regiao) {
201	        BigDecimal seguro = subtotalProdutos.multiply(regiao.getPercentualSeguro());
202	        return Arredondamento.arredondar(seguro);
203	    }
204	
205	    private BigDecimal calcularTotalPedido(
206	        BigDecimal subtotal,
207	        BigDecimal desconto,
208	        BigDecimal frete,
209	        BigDecimal seguro
210	    ) {
211	        return subtotal.subtract(desconto).add(frete).add(seguro);
212	    }
213	
214	    private FormaPagamento obterFormaPagamento(String codigo) {
215	        if (codigo == null) {
216	            throw new ErroNegocioException("FORMA_PAGAMENTO_INVALIDA");
217	        }
218	        FormaPagamento forma = pagamentoFactory.obter(codigo);
219	        if (forma == null) {
220	            throw new ErroNegocioException("FORMA_PAGAMENTO_INVALIDA");
221	        }
222	        return forma;
223	    }
224	
225	    private int obterParcelas(PedidoRequest pedido) {
226	        return pedido.parcelas() != null ? pedido.parcelas() : 1;
227	    }
228	
229	    private void validarParcelamento(FormaPagamento formaPagamento, int parcelas) {
230	        if (formaPagamento instanceof com.loja.checkout.dominio.pagamento.Pix ||
231	            formaPagamento instanceof com.loja.checkout.dominio.pagamento.Boleto) {
232	            if (parcelas != 1) {
233	                throw new ErroNegocioException("PARCELAMENTO_INVALIDO");
234	            }
235	        } else if (formaPagamento instanceof com.loja.checkout.dominio.pagamento.Cartao) {
236	            if (parcelas < 1 || parcelas > 12) {
237	                throw new ErroNegocioException("PARCELAMENTO_INVALIDO");
238	            }
239	        }
240	    }
241	
242	    private void validarDisponibilidadeFormaPagamento(FormaPagamento formaPagamento, BigDecimal totalPedido) {
243	        if (!formaPagamento.estaDisponivel(totalPedido)) {
244	            throw new ErroNegocioException("FORMA_PAGAMENTO_INDISPONIVEL");
245	        }
246	    }
247	}
